drills.solution:
export function withDefaults(opts) {
  return {
    retries: opts.retries ?? 3,
    label: opts.label ?? 'job',
    verbose: opts.verbose ?? false,
  };
}

tests.code:
const input = { retries: 5 };
const out = mod.withDefaults(input);
assert.notEqual(out, input, 'return a new object');
assert.deepEqual(input, { retries: 5 });

drills.starter:
export function toQuantity(input) {
  // TODO: a non-negative whole number, or null
}

drills.solution:
export function toQuantity(input) {
  if (typeof input === 'number') {
    return Number.isInteger(input) && input >= 0 ? input : null;
  }
  if (typeof input === 'string') {
    const s = input.trim();
    return /^[0-9]+$/.test(s) ? Number(s) : null;
  }
  return null;
}

tests.code:
assert.equal(typeof mod.toQuantity, 'function', 'export a function named toQuantity');
assert.equal(mod.toQuantity('12'), 12);
assert.equal(mod.toQuantity(' 7 '), 7);

assert.equal(mod.toQuantity(3), 3);
assert.equal(mod.toQuantity(0), 0);
for (const n of [NaN, Infinity, 2.5, -1]) assert.equal(mod.toQuantity(n), null, `toQuantity(${n})`);

drills.explanation:
Split by type, then validate before converting:

```js
if (typeof input === 'number') return Number.isInteger(input) && input >= 0 ? input : null;
if (typeof input === 'string') {
  const s = input.trim();
  return /^[0-9]+$/.test(s) ? Number(s) : null;
}
return null;
```

The regex is the validation and `Number(s)` is only the conversion. Converting first and checking the number afterwards does not work: `Number('')` and `Number('   ')` are 0, which `Number.isInteger` accepts, so the test "a blank field is null, not 0 (boundary)" fails, and `Number('1e3')` is 1000, so "'12px', '-1', '1e3' and '2.5' are rejected" fails too. `parseInt(s, 10)` is no better, because it reads '12px' as 12. On the number branch, `Number.isInteger` rejects `NaN`, `Infinity` and fractions in one call, and `input >= 0` rejects negatives.
